<script setup lang="ts">
import ForumInlineReplies from "../components/ForumInlineReplies.vue";
import {ref,computed,watch,nextTick,onMounted,onScopeDispose} from 'vue';import {useI18n} from 'vue-i18n';import {useRoute,useRouter} from 'vue-router';import {assetUrl} from '../lib/urls';
import {forumUser as user,forumToken as token,forumInbox as inbox,forumUnread as unread,type ReplyNotice} from '../stores/community';import {communityApi as api,refreshForumInbox,type ForumPost as Post} from '../api/community';import content from '../../../../services/public-reference/community-content.json';
const {locale}=useI18n(),route=useRoute(),router=useRouter(),zh=computed(()=>locale.value==='zh-CN'),label=(cn:string,en:string)=>zh.value?cn:en;
const inlineTopic=ref(0),rootPosts=ref<Post[]>([]);
const posts=ref<Post[]>([]),queue=ref<Post[]>([]),topic=ref<Post|null>(null),replyTo=ref<Post|null>(null),busy=ref(false),loading=ref(false),message=ref(''),inboxOpen=ref(false),hasMore=ref(false),limit=ref(50),newMessages=ref(0),picker=ref(false);
const mode=ref('login'),name=ref(''),password=ref(''),accept=ref(false),title=ref(''),body=ref(''),sticker=ref(''),reportId=ref(0),reason=ref(''),confirmName=ref(''),composer=ref<HTMLTextAreaElement|null>(null),stream=ref<HTMLElement|null>(null);
const emojis=['🏎️','🏁','🏆','🔥','💪','😂','🙌','❤️','👏','😭','👍','🤔','😎','🤝','🌧️','🚀','🎉','🥇','⚡','🛞','😅','👀','💯','🫡'];const stickerFor=(id:string|null|undefined)=>content.stickers.find(s=>s.id===id);const topicId=computed(()=>{const id=Number(route.query.topic);return Number.isSafeInteger(id)&&id>0?id:0;});
const status=(value:string)=>({published:label('已公开','Published'),pending:label('待审核，仅自己可见','Pending; only visible to you'),reported:label('待复核','Under review'),rejected:label('未通过审核','Not approved')}[value]||value);
let sequence=0,timer:ReturnType<typeof setInterval>|undefined,disposed=false;
function focusAccount(){document.getElementById('forum-account')?.scrollIntoView({behavior:'smooth',block:'start'});}
function bottom(){if(stream.value)stream.value.scrollTop=stream.value.scrollHeight;newMessages.value=0;}
async function refresh(initial=false){
 const id=topicId.value,seq=++sequence;loading.value=initial;const wasBottom=!stream.value||stream.value.scrollHeight-stream.value.scrollTop-stream.value.clientHeight<80,oldIds=new Set(posts.value.map(p=>p.id));
 try{const [result,root]=await Promise.all([api<{items:Post[];hasMore:boolean}>('posts'+(id?'?parent='+id+'&limit='+limit.value:'')),id?api<{item:Post}>('topic?id='+id):Promise.resolve(null)]);if(disposed||seq!==sequence||id!==topicId.value)return;posts.value=result.items;if(!id)rootPosts.value=result.items;hasMore.value=result.hasMore;topic.value=root?.item||null;if(id&&!initial&&!wasBottom)newMessages.value+=result.items.filter(p=>!oldIds.has(p.id)).length;await nextTick();if(id&&(initial||wasBottom))bottom();if(initial&&route.query.message){document.getElementById('forum-message-'+Number(route.query.message))?.scrollIntoView({block:'nearest'});}}
 catch(error){if(!disposed&&seq===sequence){message.value=error instanceof Error?error.message:'Service unavailable';if(id){topic.value=null;posts.value=[];}}}finally{if(seq===sequence)loading.value=false;}
 if(user.value?.admin){try{const result=await api<{items:Post[]}>('moderation');if(!disposed&&seq===sequence)queue.value=result.items;}catch{/* Main error is displayed by refresh. */}}
}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action();}catch(error){message.value=error instanceof Error?error.message:'Service unavailable';}finally{busy.value=false;}}
function select(id:number|null){replyTo.value=null;body.value='';sticker.value='';picker.value=false;void router.push(id?{path:'/forum',query:{topic:String(id)}}:'/forum');}
async function older(){const element=stream.value,oldHeight=element?.scrollHeight||0,oldTop=element?.scrollTop||0;limit.value=Math.min(200,limit.value+50);await refresh();await nextTick();if(element)element.scrollTop=oldTop+element.scrollHeight-oldHeight;}
function login(){void run(async()=>{const value=await api<{token:string;user:NonNullable<typeof user.value>}>(mode.value,{name:name.value,password:password.value,accept:accept.value});token.value=value.token;user.value=value.user;password.value='';await refresh(true);await refreshForumInbox();});}
function publish(){void run(async()=>{await api('posts',{title:topic.value?('回复 / Reply: '+topic.value.title).slice(0,120):title.value,body:body.value,sticker:sticker.value||null,parent:topic.value?.id,replyTo:replyTo.value?.id});title.value='';body.value='';sticker.value='';replyTo.value=null;picker.value=false;message.value=label('已发送，审核通过后公开；你可以先看到自己的消息。','Sent. Your message is visible to you and becomes public after approval.');await refresh(true);await refreshForumInbox();});}
function quote(post:Post){replyTo.value=post;void nextTick(()=>composer.value?.focus());}
async function emoji(value:string){const field=composer.value,start=field?.selectionStart??body.value.length,end=field?.selectionEnd??start;if(body.value.length-end+start+value.length>5000)return;body.value=body.value.slice(0,start)+value+body.value.slice(end);await nextTick();field?.focus();field?.setSelectionRange(start+value.length,start+value.length);}
function moderate(id:number,state:string){void run(async()=>{await api('moderate',{id,status:state});await refresh();await refreshForumInbox();});}
function remove(id:number){void run(async()=>{await api('delete',{id});if(id===topicId.value)await router.replace('/forum');await refresh();await refreshForumInbox();});}
function logout(){void run(async()=>{await api('logout',{});user.value=null;token.value='';inboxOpen.value=false;replyTo.value=null;await refresh(true);});}
function reportPost(id:number){reportId.value=id;void nextTick(()=>{document.getElementById('forum-report')?.scrollIntoView({behavior:'smooth',block:'center'});});}
function report(){void run(async()=>{await api('report',{id:reportId.value,reason:reason.value});reportId.value=0;reason.value='';message.value=label('举报已提交，内容暂停公开并等待复核。','Reported. The content is hidden pending review.');await refresh();await refreshForumInbox();});}
function deleteAccount(){void run(async()=>{await api('delete-account',{confirm:confirmName.value});user.value=null;token.value='';confirmName.value='';await router.replace('/forum');await refresh(true);});}
function openNotice(notice:ReplyNotice){void run(async()=>{await api('notifications/read',{id:notice.id});await refreshForumInbox();inboxOpen.value=false;await router.push({path:'/forum',query:{topic:String(notice.topic_id),message:String(notice.message_id)}});});}
function markAll(){void run(async()=>{await api('notifications/read',{all:true});await refreshForumInbox();});}
function visible(){if(document.visibilityState==='visible'){void refresh();if(token.value)void refreshForumInbox();}}
watch(()=>route.fullPath,(_next,previous)=>{if(route.path!=='/forum')return;if(previous){body.value='';sticker.value='';picker.value=false;title.value='';}limit.value=50;replyTo.value=null;inboxOpen.value=route.query.inbox==='1';topic.value=null;posts.value=topicId.value?[]:rootPosts.value;inlineTopic.value=0;void refresh(true);},{immediate:true});
watch(token,()=>{rootPosts.value=[];posts.value=[];inlineTopic.value=0;});
onMounted(()=>{timer=setInterval(visible,8000);document.addEventListener('visibilitychange',visible);if(token.value)void refreshForumInbox();});onScopeDispose(()=>{disposed=true;sequence++;clearInterval(timer);document.removeEventListener('visibilitychange',visible);});
</script>
<template>
<div class="page-heading"><div><p class="eyebrow">NOBI / PADDOCK CHAT</p><h1 tabindex="-1">{{label('车迷论坛','Fan forum')}}</h1><p class="muted">{{label('把赛后讨论，聊成一场新的相遇。','Keep the conversation going after the chequered flag.')}}</p></div><button v-if="user" class="button forum-inbox-toggle" :aria-expanded="inboxOpen" @click="inboxOpen=!inboxOpen">{{label('回复消息','Replies')}} <b v-if="unread" class="forum-count">{{unread}}</b></button></div>
<details class="world-preferences forum-policy"><summary>{{label('社区规则与账号隐私','Community rules & account privacy')}}</summary><p>{{label('赛车话题，友善交流。消息与表情经审核后公开，自己的待审核消息仅自己及管理员可见。禁止违法信息、辱骂、泄露隐私和未经许可的转载。账号无需邮箱，暂不支持自助找回密码；登录凭证仅保留在页面内存。回复提醒为站内通知，保留 90 天。注销会删除账号、帖子、回复及相关提醒。','Racing discussion with respect. Messages and stickers become public after moderation; pending messages are visible only to their author and moderators. No illegal content, abuse, private information or unlicensed reposts. No email or self-service password recovery. Sessions stay in page memory. In-app reply notices are retained for 90 days. Account deletion removes posts, replies and related notices.')}}</p><RouterLink to="/legal">{{label('隐私与来源说明','Privacy & sources')}} ↗</RouterLink></details>
<p v-if="message" role="status" class="notice">{{message}}</p>
<section v-if="user&&inboxOpen" class="forum-inbox world-preferences"><div class="section-heading"><h2>{{label('回复我的','Replies to me')}}</h2><button class="button" :disabled="busy||!unread" @click="markAll">{{label('全部已读','Mark all read')}}</button></div><button v-for="notice in inbox" :key="notice.id" class="forum-notice" :class="{unread:!notice.read_at}" @click="openNotice(notice)"><span>{{notice.author}} {{label('回复了讨论','replied in')}} · {{notice.title}}</span><p>{{notice.body||label('发送了一张表情贴纸','Sent a sticker')}}</p><small>{{new Date(notice.created).toLocaleString(locale)}}</small></button><p v-if="!inbox.length" class="empty-inline">{{label('还没有回复提醒。参与讨论后，相关回复会出现在这里。','No reply notices yet. Replies to your conversations will appear here.')}}</p></section>
<section v-if="!user" id="forum-account" class="world-preferences forum-account"><h2>{{label('加入围场','Join the paddock')}}</h2><div class="filter-group"><button :aria-pressed="mode==='login'" @click="mode='login'">{{label('登录','Sign in')}}</button><button :aria-pressed="mode==='register'" @click="mode='register'">{{label('注册','Register')}}</button></div><form class="forum-form" @submit.prevent="login"><label>{{label('用户名（3–24 位字母、数字、下划线）','Username (3–24 letters, digits, underscores)')}}<input v-model="name" autocomplete="username" minlength="3" maxlength="24" pattern="[A-Za-z0-9_]+" required/></label><label>{{label('密码（至少 12 位）','Password (at least 12 characters)')}}<input v-model="password" type="password" :autocomplete="mode==='register'?'new-password':'current-password'" minlength="12" maxlength="128" required/></label><label v-if="mode==='register'"><input v-model="accept" type="checkbox" required/>{{label('同意上述社区规则与账号隐私说明','I accept the community rules and account privacy terms')}}</label><button class="button primary" :disabled="busy">{{mode==='register'?label('创建账号','Create account'):label('登录','Sign in')}}</button></form></section>
<div v-else class="forum-member"><span>{{label('你好，','Hello, ')}}<strong>{{user.name}}</strong></span><button class="button" :disabled="busy" @click="logout">{{label('退出','Sign out')}}</button></div>
<section class="forum-conversation"><div class="section-heading"><div><p class="eyebrow">{{topic?'CONVERSATION':'TOPICS'}}</p><h2>{{topic?topic.title:label('围场讨论','Paddock discussions')}}</h2></div><div class="forum-inline-actions"><button v-if="topicId" class="button" @click="select(null)">{{label('返回主题','All topics')}}</button><button class="button" :disabled="loading" @click="refresh()">{{label('刷新','Refresh')}}</button></div></div>
<p v-if="loading" role="status">{{label('正在加载讨论…','Loading conversations…')}}</p>
<template v-if="!topicId"><div class="forum-topics"><article v-for="post in posts" :key="post.id" class="forum-topic-card"><button class="forum-title" @click="select(post.id)">{{post.title}}</button><p>{{post.body.slice(0,180)}}</p><img v-if="stickerFor(post.sticker)" class="forum-sticker small" :src="assetUrl(stickerFor(post.sticker)!.src)" :alt="zh?stickerFor(post.sticker)!.zh:stickerFor(post.sticker)!.en"/><p class="caption">{{post.author}} · {{new Date(post.created).toLocaleString(locale)}} · {{post.replies||0}} {{label('条回复','replies')}} · {{status(post.status)}}</p><div class="forum-inline-actions"><button v-if="user" class="button" @click="reportPost(post.id)">{{label('举报','Report')}}</button><button v-if="post.own||user?.admin" class="button" :disabled="busy" @click="remove(post.id)">{{label('删除','Delete')}}</button></div><ForumInlineReplies v-if="post.status==='published'" :post="post" :open="inlineTopic===post.id" @toggle="inlineTopic=inlineTopic===post.id?0:post.id" @changed="refresh()" @conversation="select" @login="focusAccount" @report="reportPost"/></article></div><p v-if="!posts.length&&!loading" class="empty-inline">{{label('还没有公开讨论，欢迎发起第一个话题。','No public discussions yet. Start the first topic.')}}</p></template>
<template v-else-if="topic"><article class="forum-topic-intro"><p class="forum-body">{{topic.body}}</p><img v-if="stickerFor(topic.sticker)" class="forum-sticker" :src="assetUrl(stickerFor(topic.sticker)!.src)" :alt="zh?stickerFor(topic.sticker)!.zh:stickerFor(topic.sticker)!.en"/><p class="caption">{{topic.author}} · {{status(topic.status)}}</p><button v-if="user&&topic.status==='published'" class="button" @click="quote(topic)">{{label('回复主题','Reply to topic')}}</button><button v-if="topic.own||user?.admin" class="button" :disabled="busy" @click="remove(topic.id)">{{label('删除主题','Delete topic')}}</button></article><div ref="stream" class="forum-chat-stream" role="log" :aria-label="label('聊天消息','Conversation messages')" aria-relevant="additions text"><button v-if="hasMore&&limit<200" class="button forum-older" :disabled="loading" @click="older">{{label('加载更早消息','Load earlier messages')}}</button><p v-if="hasMore&&limit>=200" class="caption">{{label('当前显示最近 200 条消息。','Showing the latest 200 messages.')}}</p><article v-for="post in posts" :id="'forum-message-'+post.id" :key="post.id" class="forum-chat-message" :class="{own:post.own}"><span class="forum-avatar" aria-hidden="true">{{post.author.slice(0,1).toUpperCase()}}</span><div class="forum-chat-bubble"><p class="forum-chat-meta"><strong>{{post.author}}</strong><time :datetime="post.created">{{new Date(post.created).toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'})}}</time></p><blockquote v-if="post.reply_to&&post.reply_to!==topic.id"><strong>{{post.quote_author||label('引用消息','Quoted message')}}</strong><p>{{post.quote_body||(post.quote_sticker?label('表情贴纸','Sticker'):label('引用内容已不可用','Quoted content unavailable'))}}</p></blockquote><p v-if="post.body" class="forum-body">{{post.body}}</p><img v-if="stickerFor(post.sticker)" class="forum-sticker" :src="assetUrl(stickerFor(post.sticker)!.src)" :alt="zh?stickerFor(post.sticker)!.zh:stickerFor(post.sticker)!.en"/><p v-if="post.status!=='published'" class="forum-message-status">{{status(post.status)}}</p><div class="forum-message-actions"><button v-if="user&&post.status==='published'" @click="quote(post)">{{label('回复','Reply')}}</button><button v-if="user" @click="reportPost(post.id)">{{label('举报','Report')}}</button><button v-if="post.own||user?.admin" :disabled="busy" @click="remove(post.id)">{{label('删除','Delete')}}</button></div></div></article><p v-if="!posts.length&&!loading" class="empty-inline">{{label('还没有回复，来聊聊你的看法。','No replies yet. Share your perspective.')}}</p></div><button v-if="newMessages" class="button" @click="bottom">{{newMessages}} {{label('条新消息，点击查看','new messages — show')}}</button></template>
</section>
<section v-if="user&&(!topicId||topic?.status==='published')" class="world-preferences forum-compose"><form class="forum-form" @submit.prevent="publish"><h2>{{topic?label('发送回复','Send a reply'):label('发起话题','Start a topic')}}</h2><label v-if="!topicId">{{label('标题','Title')}}<input v-model="title" minlength="3" maxlength="120" required/></label><div v-if="replyTo" class="forum-reply-target"><span>{{label('回复','Replying to')}} {{replyTo.author}} · {{replyTo.body.slice(0,80)||label('表情贴纸','Sticker')}}</span><button type="button" @click="replyTo=null">{{label('取消引用','Cancel reply')}}</button></div><label>{{label('消息内容','Message')}}<textarea ref="composer" v-model="body" :required="!sticker" maxlength="5000" :rows="topic?3:4" :placeholder="label('聊聊比赛，或选择一个表情…','Share a racing thought or choose a sticker…')"/></label><div v-if="stickerFor(sticker)" class="forum-sticker-preview"><img class="forum-sticker small" :src="assetUrl(stickerFor(sticker)!.src)" :alt="zh?stickerFor(sticker)!.zh:stickerFor(sticker)!.en"/><button type="button" @click="sticker=''">{{label('移除贴纸','Remove sticker')}}</button></div><div class="forum-composer-actions"><button type="button" class="button" :aria-expanded="picker" @click="picker=!picker">☺ {{label('表情 / 贴纸','Emoji / stickers')}}</button><span class="caption">{{body.length}} / 5000</span><button class="button primary" :disabled="busy||(!body.trim()&&!sticker)">{{busy?label('发送中…','Sending…'):label('发送','Send')}}</button></div><div v-if="picker" class="forum-picker" data-swipe-ignore><p class="caption">{{label('表情','Emoji')}}</p><div class="forum-emoji-grid"><button v-for="item in emojis" :key="item" type="button" :aria-label="item" @click="emoji(item)">{{item}}</button></div><p class="caption">{{label('NOBI 原创贴纸','NOBI original stickers')}}</p><div class="forum-sticker-grid"><button v-for="item in content.stickers" :key="item.id" type="button" :aria-label="zh?item.zh:item.en" :aria-pressed="sticker===item.id" @click="sticker=item.id"><img :src="assetUrl(item.src)" :alt="zh?item.zh:item.en"/></button></div></div><p class="caption">{{label('自动更新讨论；内容审核通过后公开。','Conversations update automatically; messages become public after approval.')}}</p></form></section>
<section v-if="user?.admin" class="world-preferences"><h2>{{label('管理员审核','Moderation queue')}}</h2><article v-for="post in queue" :key="post.id" class="forum-post"><h3>{{post.title}}</h3><p class="forum-body">{{post.body}}</p><img v-if="stickerFor(post.sticker)" class="forum-sticker small" :src="assetUrl(stickerFor(post.sticker)!.src)" :alt="zh?stickerFor(post.sticker)!.zh:stickerFor(post.sticker)!.en"/><p>{{post.author}} · {{status(post.status)}} · {{label('举报','Reports')}} {{post.reports}}</p><button class="button" :disabled="busy" @click="moderate(post.id,'published')">{{label('通过并公开','Approve')}}</button><button class="button" :disabled="busy" @click="moderate(post.id,'rejected')">{{label('拒绝','Reject')}}</button></article><p v-if="!queue.length">{{label('暂无待审核内容','No pending content')}}</p></section>
<form id="forum-report" v-if="reportId" class="forum-form world-preferences" @submit.prevent="report"><label>{{label('举报原因','Report reason')}}<textarea v-model="reason" minlength="3" maxlength="500" required/></label><button class="button" :disabled="busy">{{label('提交举报','Send report')}}</button><button type="button" class="button" @click="reportId=0">{{label('取消','Cancel')}}</button></form>
<details v-if="user&&!user.admin" class="world-preferences"><summary>{{label('注销账号','Delete account')}}</summary><p>{{label('账号及发布内容将被删除；请输入用户名确认。','Your account and content will be deleted. Type your username to confirm.')}}</p><form @submit.prevent="deleteAccount"><input v-model="confirmName" :placeholder="user.name" required/><button class="button" :disabled="busy||confirmName!==user.name">{{label('注销账号并删除内容','Delete account and content')}}</button></form></details>
</template>
